import{z as p,x as D,o as s,c as d,q as r,j as i,D as e,d as o,s as n,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"曝光–散焦工艺窗口","description":"","frontmatter":{"title":"曝光–散焦工艺窗口","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ed-process-window.md","filePath":"litho/ed-process-window.md","lastUpdated":1791413859000}'),m={name:"litho/ed-process-window.md"};function h(A,a,B,c,u,f){const l=D("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="曝光–散焦工艺窗口" tabindex="-1">曝光–散焦工艺窗口 <a class="header-anchor" href="#曝光–散焦工艺窗口" aria-label="Permalink to &quot;曝光–散焦工艺窗口&quot;">​</a></h1><div class="epigraph"><p>Bossung 曲线把 CD 画成离焦的函数、按剂量分族；还活着的那块曝光–散焦区域，才是这一层的工艺窗口。</p><footer>—— 据 Mack 对 E–D 窗口与 Bossung 曲线的定义；产线形式亦见 Levinson</footer></div><p><a href="/litho/stochastic-holes">上一课</a>（随机缺陷与缺失孔）。在此之上，记录介质的分叉写完：CAR 还是金属氧化物，平均行为都已经能接到显影曲线上。缺口是：产线合格与否不是「最佳焦距上 CD 对了」，而是剂量与焦距同时漂的时候 CD（以及侧壁、残胶）是否仍在规格内。本课钉曝光–散焦（E–D）窗口。窗心在场内怎么落成设定焦与指纹，留给<a href="/litho/fem-matrix">下一课</a>的焦散矩阵；CD 从哪台仪器读来，是后面<a href="/litho/cd-sem-scatterometry">CD-SEM 与散射测量</a>一课的计量链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/depth-of-focus">焦深</a>给出光学轴向尺度 \\(\\propto\\lambda/\\mathrm{NA}^2\\)；<a href="/litho/resist-contrast-curve">衬度曲线</a>给出剂量轴上的 \\(\\gamma\\)。两者正交，合格区是平面上的一块面积。只报「DOF = 120 nm」而不报剂量范围，等于把窗口压成一条线段。缺口因此是把两个轴画在一起，而不是再选一次胶。</p><p><span class="marginnote">E–D 窗口翻译成大白话：把「剂量能漂多少」（E 轴）和「焦距能偏多少」（D 轴）画成一张二维地图，所有 CD 仍合格的位置构成地图上一块面积——这块面积就是窗口。面积越大，产线越不怕机器与材料的抖动。</span></p><p>Bossung 图：横轴离焦，纵轴 CD，每条曲线一个剂量。规格带（例如目标 \\(\\pm 10\\%\\)）去切这些曲线，得到每个剂量下的可用焦深；再对剂量扫描，得到窗口。曝光宽容度（EL）常写成窗口在最佳焦距处的剂量相对宽度。</p><p><span class="marginnote">数字实例：若某层最佳焦处 EL 为 ±10%、可用焦深 200 nm，那么离焦到 100 nm（半程）时，EL 往往已掉到 ±5% 上下——两个轴不是各管各的，而是同一块面积的两种切法，这正是必须画成 E–D 图的原因。</span></p><p><span class="marginnote">常见误区：把「DOF = 120 nm」当成这层的完整工艺余量。DOF 只是最佳剂量下的一条线段；剂量同时漂 ±5% 时，可用焦深可能只剩几十纳米。合格判据必须剂量与焦距一起报。</span></p><h3 id="重叠窗口才是层的窗口" tabindex="-1">重叠窗口才是层的窗口 <a class="header-anchor" href="#重叠窗口才是层的窗口" aria-label="Permalink to &quot;重叠窗口才是层的窗口&quot;">​</a></h3><p>密线、孤立线、孔、反向线的 Bossung 形状不同，常有「禁戒节距」。层的工艺窗口是各类关键图形合格区的交集。RET 把某一节距的窗做大，可能把另一类切掉。上一课程的 \\(k_1\\) 窗口，在这里变成可测量的面积。</p><p><span class="marginnote">剂量的单位是 \\(\\mathrm{mJ/cm^2}\\)，离焦是纳米。不要把归一化的 EL 百分比和焦深纳米加在同一个「越大越好」的榜上而不声明图形。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>曝光矩阵：晶圆上按场变剂量、变焦距（或用楔形调焦），显影后量 CD。得到 Bossung，切规格，画 E–D 图。也可以在模拟器里用校准过的抗蚀剂模型扫同一平面，但验收以硅片矩阵为准。</p><p>判据除 CD 外常加：侧壁角、膜残留、桥连/断开。EUV 随机失效（缺孔）会在窗口边沿先于平均 CD 越界——那是随机课的尾部，本课的窗口默认是平均 CD 的合格区，可另叠加缺陷判据。</p><h3 id="与-nils-的关系" tabindex="-1">与 NILS 的关系 <a class="header-anchor" href="#与-nils-的关系" aria-label="Permalink to &quot;与 NILS 的关系&quot;">​</a></h3><p>NILS 高，同样的剂量误差引起的 \\(\\Delta\\mathrm{CD}\\) 小，EL 宽。离焦掉 NILS，窗在焦轴上收窄。因此空中像课把 NILS 当窗口的光学预言；本课是胶切完之后的实现。预言与实现差一截，差在 \\(\\ell\\)、\\(\\gamma\\) 和计量偏置。</p>',17)),(s(),i(E,null,{default:e(()=>[n(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E7%A6%BB%E7%84%A6%22%5D%20--%3E%20BOSS%5B%22Bossung%3A%20CD(z%2C%20E)%22%5D%0A%20%20E%5B%22%E5%89%82%E9%87%8F%20E%22%5D%20--%3E%20BOSS%0A%20%20BOSS%20--%3E%20SPEC%5B%22CD%20%E8%A7%84%E6%A0%BC%E5%B8%A6%22%5D%0A%20%20SPEC%20--%3E%20ED%5B%22E%E2%80%93D%20%E7%AA%97%E5%8F%A3%22%5D%0A%20%20ED%20--%3E%20OV%5B%22%E5%A4%9A%E5%9B%BE%E5%BD%A2%E9%87%8D%E5%8F%A0%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"最佳焦距附近，剂量主要沿衬度曲线移动等剂量面，CD 单调变。离焦后空中像调制变浅，要维持同一 CD 往往需要改剂量，Bossung 出现弯曲甚至「通过焦点的 CD 翻面」。三束成像的窗更瘦，两束成像（离轴）常在焦轴上更宽——机制在焦深课讲过，这里只是把它读成面积。",-1)),(s(),i(E,null,{default:e(()=>[n(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20DEF%5B%22%E7%A6%BB%E7%84%A6%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20MOD%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E8%B0%83%E5%88%B6%E5%8F%98%E6%B5%85%22%5D%0A%20%20MOD%20--%3E%20DOSE%5B%22%E7%BB%B4%E6%8C%81%20CD%20%E9%9C%80%E8%A1%A5%E5%81%BF%E5%89%82%E9%87%8F%22%5D%0A%20%20DOSE%20--%3E%20BEND%5B%22Bossung%20%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20MOD%20--%3E%20DROP%5B%22NILS%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DROP%20--%3E%20SENS%5B%22%E5%89%82%E9%87%8F%E6%95%8F%E6%84%9F%E5%BA%A6%E5%8D%87%E9%AB%98%22%5D%0A%20%20SENS%20--%3E%20NARROW%5B%22EL%20%E6%94%B6%E7%AA%84%EF%BC%9A%E7%AA%97%E5%8F%A3%E5%8F%98%E5%B0%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>浸没与 High-NA 把焦轴预算削薄，窗口先在 \\(z\\) 方向死。换胶课主要改剂量轴与模糊，对焦轴的帮助有限。所以「换金属氧化物胶」不是对 \\(\\mathrm{NA}^2\\) 惩罚的回答。</p><h3 id="套刻不画进本课的平面" tabindex="-1">套刻不画进本课的平面 <a class="header-anchor" href="#套刻不画进本课的平面" aria-label="Permalink to &quot;套刻不画进本课的平面&quot;">​</a></h3><p>E–D 窗管的是同一层图形的尺寸。套刻管的是相对另一层（或同层另一次曝光）的位置。LELE 的节距误差来自套刻，CD 误差来自各自的 E–D；两张窗相乘，不能把 overlay 纳米数画进 \\((E,z)\\) 冒充面积。标记如何量位置，是后课。</p><p><span class="marginnote">Bossung 在某些剂量下几乎通过焦点不变，那是 isofocal 附近。孤立与密线的 isofocal 剂量往往不同，overlap 仍可能瘦。不要把一条线的 isofocal 写成整层的免费焦深。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>窗口不含套刻、不含跨场镜头指纹的全部、不含刻蚀后的最终 CD——除非量的就是刻蚀后。轨道带来的 PEB 不均匀会把名义窗切碎，那是工艺控制，不改 E–D 定义。在后面的计量课接手之前，本课假设 CD 是「真值」；计量偏置会系统平移 Bossung，必须分开校准。</p><p>曝光矩阵本身消耗晶圆与机时，产线常用少量场加模拟补密。模拟没有校准过的 \\(\\ell\\)、\\(\\gamma\\) 时，窗口面积不可信。禁戒节距要在照明固定后扫节距，而不是只扫剂量焦距。</p><p><span class="marginnote">EL 与 DOF 常被收成一个「窗口面积」百分数。比较不同层时必须同一规格带、同一图形集，否则面积竞赛无意义。</span></p><p>后课默认：说到工艺窗口就是 E–D 平面上的重叠合格区，不再与光学 DOF 公式混成一个数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工艺窗口是剂量–离焦平面上的合格面积，Bossung 是它的切片。</li><li>层窗口 = 关键图形类别的交集，不是最好看的那条线栅。</li><li>NILS 预言 EL；胶的 \\(\\ell\\) 与 \\(\\gamma\\) 把预言变成实现。</li><li>换胶主要动剂量轴，抬 NA 主要罚焦轴。</li><li>场内指纹与 FEM 是下一课；CD 如何量，交给计量课。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>；Levinson, <em>Principles of Lithography</em>。</li></ul>',11))])}const g=p(m,[["render",h]]);export{S as __pageData,g as default};
